// discount (without trailing zeros), `discount` what it takes off quantity x unit price, and
// `amount` is after it. `unitType` is the unit the line is billed in (hour, day, ...), null when none.
export interface InvoiceLineView {
  id: number;
  description: string;
  qty: string;
  unitType: string | null;
  unitPrice: string;
  discountPct: string;
  discount: string;
  amount: string;
  discountShare: string;
  tax: string;
  // The line's amount before tax: its amount less its discount share, less the tax inside it when the
  // client's prices include tax.
  net: string;
  taxExempt: boolean;
  taxRate: string | null;
  // The id of the invoice line a credit note's line credits; null when none.
  creditOfLine: number | null;
  // Whether the line is priced in progressive tiers from the client's rate card; its `unitPrice` is
  // then the first band's, and a change of quantity reprices it from the bands.
  tiered: boolean;
  // The quantity the line is billed and priced on, without trailing zeros: `qty` rounded up to the
  // next whole increment its unit type has on the client's rate card (`qty` itself without one), and
  // then at least the minimum units it has there.
  billedQty: string;
}

// A payment made to an opened invoice: the whole amount paid and `allocated`, how much of it went to
// this invoice, decimal strings to the cent; the date it was paid (yyyy-mm-dd) and the RF reference it
// A line to add to a draft: quantity, unit type, unit price, the line's own discount percentage and
// its own tax rate as entered (each left out when none), checked again by the server. A line with a
// unit type and no unit price is priced at the client's rate for that unit type.
export interface NewLine {
  description: string;
  qty: string;
  unitType?: string;
  unitPrice?: string;
  taxExempt: boolean;
  discountPct?: string;
  taxRate?: string;
}

// A discount to give: either a percentage or a fixed amount, as entered, with an optional cap on
// what a percentage takes off and an optional reason, needed when it takes off more than a fifth of the subtotal.
export type NewDiscount = ({ discountPct: string } | { discountAmount: string }) & { discountCap?: string; discountReason?: string };
              <th scope="col">Tax rate</th>
              <th scope="col">Tax</th>
              <th scope="col">Net</th>
              <th scope="col">Actions</th>
            </tr>
          </thead>
          <tbody>
            @for (l of inv.lines; track l.id) {
              <tr [attr.data-testid]="'line-row-' + l.id">
                <td data-testid="line-description">{{ l.description }}</td>
                <td data-testid="line-qty">{{ l.qty }}</td>
                <td data-testid="line-billed-qty">{{ l.billedQty }}</td>
                <td data-testid="line-unit-type">{{ l.unitType ?? '' }}</td>
                <td data-testid="line-unit-price">{{ l.tiered ? 'Tiered from ' + amount(l.unitPrice) : amount(l.unitPrice) }}</td>
                <td data-testid="line-discount">{{ amount(l.discount) }}</td>
                <td data-testid="line-amount">{{ amount(l.amount) }}</td>
                <td data-testid="line-discount-share">{{ amount(l.discountShare) }}</td>
                <td data-testid="line-tax-exempt">{{ l.taxExempt ? 'Exempt' : 'Taxable' }}</td>
                <td data-testid="line-tax-rate">{{ (l.taxRate ?? inv.taxRate) + '%' }}</td>
                <td data-testid="line-tax">{{ amount(l.tax) }}</td>
                <td data-testid="line-net">{{ amount(l.net) }}</td>
                <td>
                  <button
                    type="button"
                    data-testid="line-edit"
                    [disabled]="saving()"
        }
        @if (voidError()) {
          <p role="alert" data-testid="invoice-void-error">{{ voidError() }}</p>
        }

        <form [formGroup]="form" (ngSubmit)="saveLine(inv.id)" [attr.aria-label]="editingLineId() === null ? 'Add a line' : 'Edit a line'" novalidate>
          <label for="line-description">Description</label>
          <input
            id="line-description"
            data-testid="line-form-description"
            formControlName="description"
            required
          />
          <label for="line-qty">Quantity</label>
          <input
            id="line-qty"
            data-testid="line-form-qty"
            inputmode="decimal"
            formControlName="qty"
            required
          />
          <label for="line-unit-type">Unit type (optional, e.g. hour)</label>
          <input
            id="line-unit-type"
            data-testid="line-form-unit-type"
            formControlName="unitType"
          />
          <label for="line-unit-price">Unit price ({{ symbol() }}, optional with a unit type on the rate card or price list)</label>
          <input
            id="line-unit-price"
            data-testid="line-form-unit-price"
            inputmode="decimal"
            formControlName="unitPrice"
          />
          <label for="line-discount-pct">Line discount (%, optional)</label>
          <input
            id="line-discount-pct"
            data-testid="line-form-discount-pct"
            inputmode="decimal"
            formControlName="discountPct"
          />
          <label for="line-tax-rate">Tax rate (%, optional)</label>
          <input
            id="line-tax-rate"
            data-testid="line-form-tax-rate"
            inputmode="decimal"
            formControlName="taxRate"
          />
          <input
            id="line-exempt"
            type="checkbox"
            data-testid="line-form-exempt"
            formControlName="taxExempt"
          />
          <label for="line-exempt">Tax exempt</label>
          <button type="submit" data-testid="line-form-submit" [disabled]="saving()">
            {{ editingLineId() === null ? 'Add line' : 'Save line' }}
          </button>
          @if (editingLineId() !== null) {
            <button type="button" (click)="cancelEdit()">Cancel</button>
          }
          @if (error()) {
            <p role="alert" data-testid="line-form-error">{{ error() }}</p>
          }
        </form>

